-- Premier Five League (Sport)
-- Generated by gen_datasets.py with a fixed seed. Fictional data.

DROP TABLE IF EXISTS transfers; DROP TABLE IF EXISTS goals; DROP TABLE IF EXISTS matches;
DROP TABLE IF EXISTS staff; DROP TABLE IF EXISTS players; DROP TABLE IF EXISTS teams;
CREATE TABLE teams (team_id INT PRIMARY KEY, team_name VARCHAR(60) COLLATE NOCASE NOT NULL, city VARCHAR(60) COLLATE NOCASE, founded_year INT, stadium VARCHAR(60) COLLATE NOCASE, capacity INT);
CREATE TABLE players (player_id INT PRIMARY KEY, team_id INT REFERENCES teams(team_id), first_name VARCHAR(60) COLLATE NOCASE NOT NULL, last_name VARCHAR(60) COLLATE NOCASE NOT NULL,
  position VARCHAR(2) COLLATE NOCASE, nationality VARCHAR(60) COLLATE NOCASE, birth_date DATE, market_value_usd DECIMAL(12,2), shirt_number INT);
CREATE TABLE staff (staff_id INT PRIMARY KEY, team_id INT REFERENCES teams(team_id), first_name VARCHAR(60) COLLATE NOCASE, last_name VARCHAR(60) COLLATE NOCASE, role VARCHAR(60) COLLATE NOCASE, reports_to INT REFERENCES staff(staff_id));
CREATE TABLE matches (match_id INT PRIMARY KEY, season INT, match_date DATE, home_team_id INT REFERENCES teams(team_id), away_team_id INT REFERENCES teams(team_id),
  home_goals INT, away_goals INT, attendance INT, referee VARCHAR(60) COLLATE NOCASE);
CREATE TABLE goals (goal_id INT PRIMARY KEY, match_id INT REFERENCES matches(match_id), player_id INT REFERENCES players(player_id), minute INT,
  assist_player_id INT REFERENCES players(player_id), is_penalty INT);
CREATE TABLE transfers (transfer_id INT PRIMARY KEY, player_id INT REFERENCES players(player_id), from_team_id INT REFERENCES teams(team_id),
  to_team_id INT REFERENCES teams(team_id), fee_usd DECIMAL(12,2), transfer_date DATE);






